        return runtime.Value.initNull();
    }
    if (std.mem.eql(u8, name, "is_callable")) {
        if (args.len > 0) return try runtime.php_is_callable(args[0]);
        return runtime.Value.initNull();
    }
    if (std.mem.eql(u8, name, "is_resource")) {
